import { button, field, select, check, text, escape } from './html.js';

export function importer(empty) {
  return `<form id="player-import"><details data-disclosure="player-import" class="card player-import"${empty ? ' open' : ''}><summary>${text('Import an exercise')}</summary><p>${text('Drop a JSON file here, choose a file, or paste JSON. Your collection starts empty.')}</p><label>${text('Exercise JSON file')}<input type="file" name="import-file" accept=".json,application/json"></label><label>${text('Paste exercise JSON')}<textarea name="import-json" rows="5" spellcheck="false"></textarea></label>${button('import', 'Import JSON')}<p>${text('Import validates the complete file before changing your current exercise.')}</p></details></form>`;
}
export function primaryControls(exercise, settings) {
  return `<section class="card player-controls" aria-label="${text('Playback')}"><div class="player-row">${button('play', 'Play / resume')}${button('pause', 'Pause')}${button('stop', 'Stop')}</div><div class="player-row">${select('variantId', 'Variant', exercise.variants.map(item => [item.id, item.name]), settings.variantId)}${field('speed', 'Practice speed (%)', settings.speed * 100, 'min="25" max="150" step="1"')}${field('seek', 'Position (ticks)', 0, 'min="0" step="1"')}${button('seek', 'Seek')}</div><div class="player-row">${exercise.tracks.map(track => `<fieldset><legend>${escape(track.name)}</legend>${check(`mute:${track.id}`, 'Mute', settings.tracks[track.id]?.mute ?? false)}${field(`volume:${track.id}`, 'Volume (%)', (settings.tracks[track.id]?.volume ?? 1) * 100, 'min="0" max="100"')}</fieldset>`).join('')}</div><p data-player-status role="status" aria-live="polite"></p><p data-player-position></p></section>`;
}
export function loopControls(variant, settings, tpq) {
  const measures = variant.measures.map(item => [item.id, item.label]);
  return `<section class="card"><h2>${text('Loops')}</h2>${check('loopEnabled', 'Repeat loop', settings.loop.enabled)}<div class="player-row">${field('loopStart', 'Start quarter beat (0 based)', settings.loop.startTick / tpq, 'min="0" step="any"')}${field('loopEnd', 'End quarter beat (exclusive)', settings.loop.endTick / tpq, 'min="0" step="any"')}${button('full-loop', 'Full exercise')}</div><div class="player-row">${select('measureStart', 'First measure', measures, variant.measures[0].id)}${select('measureEnd', 'Last measure', measures, variant.measures.at(-1).id)}${button('measure-loop', 'Use measures')}</div><p data-player-loop>${text('Selected loop')}: ${settings.loop.startTick}–${settings.loop.endTick} ${text('ticks')}</p></section>`;
}
export function secondaryControls(settings) {
  const acc = settings.acceleration;
  return `<details class="card"><summary>${text('Practice options')}</summary><div class="player-row">${field('accent', 'Accent strength (%)', settings.accent * 100, 'min="0" max="100"')}${select('metronome', 'Metronome', ['off', 'beats', 'subdivisions'].map(value => [value, text(value)]), settings.metronome)}${select('countIn', 'Count-in', ['none', 'first', 'every'].map(value => [value, text(value)]), settings.countIn)}${field('countBars', 'Count-in measures', settings.countBars, 'min="1" max="4" step="1"')}${field('gap', 'Repeat gap (seconds)', settings.gap, 'min="0" max="120" step="0.1"')}</div><p>${text('The silent gap comes first, then any count-in. Compound meters count dotted beats.')}</p><fieldset><legend>${text('Gradual acceleration')}</legend>${check('accelerate', 'Enable acceleration', acc.enabled)}<div class="player-row">${field('accStart', 'Starting speed (%)', acc.start * 100, 'min="25" max="150"')}${field('accIncrement', 'Increment (percentage points)', acc.increment, 'min="0.1" max="100" step="0.1"')}${field('accEvery', 'Repetitions per increment', acc.every, 'min="1" max="1000" step="1"')}${field('accTarget', 'Target speed (%)', acc.target * 100, 'min="25" max="150"')}</div></fieldset>${button('export-settings', 'Export practice settings')}</details>`;
}
export function correctionControls(exercise, variant, selectedId) {
  const note = variant.notes.find(item => item.id === selectedId) ?? variant.notes[0];
  if (!note) return '';
  return `<form id="player-correction"><details data-disclosure="player-correction" class="card"><summary>${text('Correct a note')}</summary>${select('noteId', 'Note event', variant.notes.map(item => [item.id, `${item.id}: MIDI ${item.pitch} @ ${item.startTick}`]), note.id)}<div class="player-row">${field('notePitch', 'MIDI pitch', note.pitch, 'min="0" max="127" step="1"')}${field('noteStart', 'Start tick', note.startTick, 'min="0" step="1"')}${field('noteDuration', 'Duration ticks', note.durationTicks, 'min="1" step="1"')}${select('noteTrack', 'Track', exercise.tracks.map(item => [item.id, item.name]), note.trackId)}${field('noteVelocity', 'Velocity', note.velocity, 'min="1" max="127" step="1"')}${check('noteAccent', 'Accent', note.accent)}</div>${button('correct', 'Save note correction')}</details></form>`;
}
